+fn git_stdout(repo_path: &Path, args: &[&str], action: &str) -> Result<String, String> {
+    let output = Command::new("git")
+        .arg("-C")
+        .arg(repo_path)
+        .args(args)
+        .output()
+        .map_err(|err| format!("failed to {action}: {err}"))?;
+    if !output.status.success() {
+        return Err(format!(
+            "failed to {action}: {}",
+            String::from_utf8_lossy(&output.stderr).trim()
+        ));
+    }
