+fn normalize_repo_path(path: &str) -> Result<String, String> {
+    let normalized = path.trim_matches('/');
+    if normalized
+        .split('/')
+        .any(|part| part == ".." || part == ".")
+        || path.starts_with('/')
+        || path.contains('\0')
+    {
+        return Err("path must be repository-relative and cannot contain . or .. components".to_string());
+    }
