+fn relative_depth(path: &str, base_path: &str) -> Option<usize> {
+    let relative = if base_path.is_empty() {
+        path
+    } else if path == base_path {
+        return Some(0);
+    } else {
+        path.strip_prefix(&format!("{base_path}/"))?
+    };
+    Some(relative.split('/').count())
+}
